fn check_native_failure_keeps_writes(ending: &str, limits: risunest_ir::Limits, reason: &str) {
    let budget = Budget::new(limits, Arc::new(AtomicBool::new(false))).unwrap();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let access = scope(&store, &pool);
    let triggers = [format!("listenEdit('editOutput', function(id, value) setChatVar(id, 'k', string.rep('v', 16)) setChat(id, 0, 'edited') {ending} end)")];
    let failure = answer(&mut host(), request(LuaMode::Script(ScriptMode::EditOutput), Value::Text(Text::from_str("a", &budget).unwrap())),
        Context { owner: "char-b", triggers: &triggers, records: Records::Store { access: &access, store: &store }, cancellation: &Cancellation::default(), budget: &budget }).unwrap_err();
    assert!(failure.reason.starts_with(reason), "{failure:?}");
    assert_eq!(failure.edits, [Edit::Variable { key: "k".into(), value: "v".repeat(16).into() }, Edit::MessageData { index: 0.0, data: "edited".into() }]);
    assert!(matches!(failure.saved.effects.as_slice(),[
        Effect::ChatVariable {name,value:Value::Text(value)},
        Effect::Message(MessageEdit::SetData {index:0.0,data:Value::Text(data)}),
    ] if name.as_unicode()==Some("k") && value.as_unicode()==Some("vvvvvvvvvvvvvvvv")
        && data.as_unicode()==Some("edited")),"{:?}",failure.saved.effects);
    commit(&access, &store);
    let stored = conversation(&store);
    assert_eq!(stored["scriptstate"]["$k"], "v".repeat(16));
    assert_eq!(stored["message"][0]["data"], "edited");
}

