// TS logs a listener timeout and goes on with the next listener. This host also drops the timed-out engine, so the next
// batch initializes it again.
#[test]
fn a_listener_timeout_continues_with_the_next_listener_and_drops_its_engine() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let mut host = timed(Duration::from_millis(250));
    let triggers = [
        "count = 0 listenEdit('editOutput', function(id, value) count = count + 1 setChatVar(id, 'before', tostring(count)) if count == 1 then while true do end end return 'reused' end)".to_owned(),
        "listenEdit('editOutput', function(id, value) setChatVar(id, 'after', value) return value .. '+' end)".to_owned(),
    ];
    for iteration in 0..2 {
        let before_revision=store.borrow().revision().unwrap();
        let access = scope(&store, &pool);
        let reply = answer(&mut host, request(LuaMode::Script(ScriptMode::EditOutput), Value::Text(Text::from_str("original", &budget).unwrap())),
            Context { owner: "char-b", triggers: &triggers, records: Records::Store { access: &access, store: &store }, cancellation: &Cancellation::default(),
                budget: &budget });
        let Ok(HostReply::Lua(LuaReply {value,effects,stop_sending}))=reply else{panic!("{reply:?}")};
        assert_eq!(text_of(&value),Some("original+"));
        assert!(!stop_sending);
        if iteration==0{
            assert!(matches!(effects.as_slice(),[
                Effect::ChatVariable {name:before,value:Value::Text(count)},Effect::ChatVariable {name:after,value:Value::Text(seen)},
            ] if before.as_unicode()==Some("before")&&count.as_unicode()==Some("1")&&after.as_unicode()==Some("after")
                &&seen.as_unicode()==Some("original")),"{effects:?}");
        }else{
            assert!(effects.is_empty(),"{effects:?}");
        }
        commit(&access, &store);
        assert_eq!(conversation(&store)["scriptstate"]["$before"], "1");
        assert_eq!(conversation(&store)["scriptstate"]["$after"], "original");
        if iteration==1{assert_eq!(store.borrow().revision().unwrap(),before_revision);}
    }
}

#[test]
fn cancellation_after_a_write_retains_edits_for_one_settlement() {
    let budget = budget();
    let rows = json!([{ "role": "user", "data": "hello", "chatId": "m1" }]);
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let access = scope(&store, &pool);
    let revision_before = store.borrow().revision().unwrap();
    let stored_before = conversation(&store);
    let cancellation = Cancellation::default();
    let triggers = ["listenEdit('editOutput', function(id, value) setChatVar(id, 'before', string.rep('v', 32768)) setChat(id,0,'ordered') setChatVar(id,'marker','ready') while true do end end)".to_owned()];
    let (reply,observed)=std::thread::scope(|threads|{
        let observer_access=access.as_ref();let observer_cancellation=cancellation.clone();
        let observer=threads.spawn(move ||{
            let expected="ready";
            let deadline=std::time::Instant::now()+Duration::from_secs(5);
            while std::time::Instant::now()<deadline{
                if observer_access.raw_pending_text_is("marker",expected){observer_cancellation.cancel();return true;}
                std::thread::yield_now();
            }
            false
        });
        let reply=answer(&mut host(),request(LuaMode::Script(ScriptMode::EditOutput),Value::Text(Text::from_str("original",&budget).unwrap())),
            Context {owner:"char-b",triggers:&triggers,records:Records::Store {access:&access,store:&store},cancellation:&cancellation,budget:&budget});
        (reply,observer.join().unwrap())
    });
    assert!(observed, "write was not observed before the deadline");
    let failure = reply.unwrap_err();
    assert_eq!(failure.reason, "lua-edit-cancelled");
    assert_eq!(failure.edits, [
        Edit::Variable { key: "before".into(), value: "v".repeat(32768).into() },
        Edit::MessageData {index:0.0,data:"ordered".into()},
        Edit::Variable {key:"marker".into(),value:"ready".into()},
    ]);
    assert!(matches!(failure.saved.effects.as_slice(),[
        before,Effect::Message(MessageEdit::SetData {index:0.0,data:Value::Text(data)}),marker,
    ] if matches!(variable(before),Some(("before",value)) if text_of(value).is_some_and(|value| value=="v".repeat(32768)))
        && data.as_unicode()==Some("ordered")
        && matches!(variable(marker),Some(("marker",value)) if text_of(value)==Some("ready"))),"{:?}",failure.saved.effects);
    assert_eq!(store.borrow().revision().unwrap(), revision_before);
    assert_eq!(conversation(&store), stored_before);
    let segment = access.next_segment().unwrap();
    let receipt = access.commit(&mut store.borrow_mut(), &segment, FinishMode::IfChanged).unwrap();
    assert_eq!(receipt.error, None);
    let revision_after = store.borrow().revision().unwrap();
    assert_eq!(revision_after, revision_before + 1);
    assert_eq!(receipt.status, super::access::SegmentStatus::Committed(revision_after));
    assert_eq!(conversation(&store)["scriptstate"]["$before"], "v".repeat(32768));
    assert_eq!(conversation(&store)["scriptstate"]["$marker"],"ready");
    assert_eq!(conversation(&store)["message"][0]["data"],"ordered");
    let retried = access.commit(&mut store.borrow_mut(), &segment, FinishMode::IfChanged).unwrap();
    assert_eq!(retried, receipt);
    assert_eq!(store.borrow().revision().unwrap(), revision_after);
    assert_eq!(conversation(&store)["scriptstate"]["$before"], "v".repeat(32768));
    assert_eq!(conversation(&store)["scriptstate"]["$marker"],"ready");
    assert_eq!(conversation(&store)["message"][0]["data"],"ordered");
}

#[test]
fn ir_cancellation_during_record_and_scalar_reads_keeps_the_acknowledged_prefix_and_allows_a_fresh_job() {
    use super::lua_edit::{Call, CallStatus};
    use std::sync::atomic::Ordering;
    let mut host = host();
    for (getter, expected) in [("getAuthorsNote(id)", "ready note"), ("getChatData(id,0)", "hello"), ("getChatRole(id,0)", "user")] {
        let cancel = Arc::new(AtomicBool::new(false));
        let cancelled_budget = Budget::new(ir_limits(), cancel.clone()).unwrap();
        let rows = json!([{"role":"user","data":"hello","chatId":"m1"}]);
        let (_directory, store) = fixture_records(&rows,&json!({}),None,Some(&json!({"note":"ready note"})));
        let pool = AccessPool::new(settings()).unwrap();
        let access = scope(&store,&pool);
        let live = source(&access,&store,&cancelled_budget);
        let shutdown = Cancellation::default();
        let code = format!("function onStart(id) if getChatVar(id,'before')=='null' then setChatVar(id,'before','acknowledged-before'); while true do {getter} end end; return {getter} end");
        let (outcome,observed)=std::thread::scope(|threads|{
            let observer_access=access.as_ref();let observer_cancel=cancel.clone();
            let observer=threads.spawn(move ||{
                let expected="acknowledged-before";let deadline=std::time::Instant::now()+Duration::from_secs(5);
                while std::time::Instant::now()<deadline{
                    if observer_access.raw_pending_text_is("before",expected){observer_cancel.store(true,Ordering::Release);return true;}
                    std::thread::yield_now();
                }
                false
            });
            let outcome=host.call(Call {owner:"char-b",code:&code,entry:"start",low_level:false,deadline:LuaDeadline::Listener,
                source:&live,cancellation:&shutdown,budget:&cancelled_budget});
            (outcome,observer.join().unwrap())
        });
        assert!(observed,"prefix was not observed for {getter}");
        let outcome = outcome.unwrap();
        assert!(!shutdown.is_cancelled(),"IR cancellation must be independent of runtime shutdown");
        assert!(cancel.load(Ordering::Acquire));
        assert_eq!(outcome.status,CallStatus::Cancelled,"{getter}");
        assert_eq!(outcome.edits,[Edit::Variable {key:"before".into(),value:"acknowledged-before".into()}]);
        assert_eq!(acknowledged_variables(&outcome.saved,&budget()),json!([["before",["string","acknowledged-before"]]]));
        assert_eq!(conversation(&store)["scriptstate"],json!({}));
        let segment = access.next_segment().unwrap();
        let receipt = access.commit_raw(&mut store.borrow_mut(),&segment,VariableFinish::Failure).unwrap();
        assert_eq!(receipt.error,None);
        let revision = store.borrow().revision().unwrap();
        assert_eq!(conversation(&store)["scriptstate"]["$before"],"acknowledged-before");
        assert_eq!(access.commit_raw(&mut store.borrow_mut(),&segment,VariableFinish::Failure).unwrap(),receipt);
        assert_eq!(store.borrow().revision().unwrap(),revision);
        drop(outcome);
        let fresh = budget();
        let outcome = host.call(Call {owner:"char-b",code:&code,entry:"start",low_level:false,deadline:LuaDeadline::Listener,
            source:&live,cancellation:&shutdown,budget:&fresh}).unwrap();
        assert_eq!(outcome.status,CallStatus::Returned,"{getter}");
        assert_eq!(text_of(&outcome.value),Some(expected),"{getter}");
        assert!(outcome.saved.variables.is_empty());
        drop(outcome);

        let current_cancel=Arc::new(AtomicBool::new(false));
        let current_budget=Budget::new(ir_limits(),current_cancel.clone()).unwrap();
        let current_code=format!("function onStart(id)setChatVar(id,'current','acknowledged-current');while true do {getter} end end");
        let (outcome,observed)=std::thread::scope(|threads|{
            let observer_access=access.as_ref();let observer_cancel=current_cancel.clone();
            let observer=threads.spawn(move ||{
                let expected="acknowledged-current";let deadline=std::time::Instant::now()+Duration::from_secs(5);
                while std::time::Instant::now()<deadline{
                    if observer_access.raw_pending_text_is("current",expected){observer_cancel.store(true,Ordering::Release);return true;}
                    std::thread::yield_now();
                }
                false
            });
            let outcome=host.call(Call {owner:"char-b",code:&current_code,entry:"start",low_level:false,deadline:LuaDeadline::Listener,
                source:&live,cancellation:&shutdown,budget:&current_budget});
            (outcome,observer.join().unwrap())
        });
        assert!(observed,"current-budget prefix was not observed for {getter}");
        let outcome=outcome.unwrap();
        assert_eq!(outcome.status,CallStatus::Cancelled,"new operational cancellation must be honored for {getter}");
        assert!(!shutdown.is_cancelled());
        assert_eq!(acknowledged_variables(&outcome.saved,&budget()),json!([["current",["string","acknowledged-current"]]]));
        live.finish_variables(VariableFinish::Failure).unwrap();
        assert_eq!(conversation(&store)["scriptstate"]["$before"],"acknowledged-before");
        assert_eq!(conversation(&store)["scriptstate"]["$current"],"acknowledged-current");
    }
}

// The oracle's character and database hold empty default variables.
fn snapshot(rows: &Json, scriptstate: &Json) -> Arc<ConversationSnapshot> {
    Arc::new(ConversationSnapshot { character: json!({ "defaultVariables": "" }), conversation: json!({ "scriptstate": scriptstate }),
        messages: rows.as_array().unwrap().clone(), root: json!({ "templateDefaultVariables": "" }) })
}

fn copy_effect(effect: &Effect, budget: &Budget) -> Effect {
    let value = |value: &Value| copy_value(value, budget).unwrap();
    let text = |text: &Text| text.copy(budget).unwrap();
    match effect {
        Effect::ChatVariable { name, value: stored } => Effect::ChatVariable { name: text(name), value: value(stored) },
        Effect::ChatField { field, value: stored } => Effect::ChatField { field: text(field), value: value(stored) },
        Effect::CharacterField { field, value: stored } => Effect::CharacterField { field: text(field), value: text(stored) },
        Effect::Message(edit) => Effect::Message(match edit {
            MessageEdit::SetData { index, data } => MessageEdit::SetData { index: *index, data: value(data) },
            MessageEdit::SetRole { index, role } => MessageEdit::SetRole { index: *index, role: *role },
            MessageEdit::Cut { start, end } => MessageEdit::Cut { start: *start, end: *end },
            MessageEdit::Append { role, data, chat_id } => MessageEdit::Append { role: *role, data: value(data), chat_id: text(chat_id) },
            MessageEdit::Remove { index } => MessageEdit::Remove { index: *index },
            MessageEdit::Insert { index, role, data, chat_id } => MessageEdit::Insert { index: *index, role: *role, data: value(data), chat_id: text(chat_id) },
            MessageEdit::Replace { messages } => MessageEdit::Replace { messages: value(messages) },
            edit => panic!("unexpected edit {edit:?}"),
        }),
        effect => panic!("unexpected effect {effect:?}"),
    }
}

// Each call reads the snapshot the case starts from, with every effect the earlier calls reported as its view, as the
// route serves a send whose store does not hold them yet.
#[test]
fn edit_batches_replayed_over_the_view_match_main_thread_wasmoon() {
    let legacy = oracle_set!("edit").into_iter().filter(|(case, _)| case.get("owner").is_none()).collect::<Vec<_>>();
    check("edit overlay replay", &legacy, |case, expected| {
        let budget = budget();
        let mut records=Arc::try_unwrap(snapshot(&case["rows"],&case["scriptstate"])).unwrap();
        if let Some(globals)=case.get("globals"){records.root["globalChatVariables"]=globals.clone();}
        if let Some(note) = case.get("authorNote") {
            for (field, input) in [("note", "note"), ("authorNotePreset", "link")] {
                if let Some(value) = note.get(input) { records.conversation[field] = value.clone(); }
            }
            if let Some(value) = note.get("presets") { records.root["authorNotePresets"] = value.clone(); }
        }
        let records=Arc::new(records);
        let mut host = host();
        let triggers = codes(case);
        let index = case["index"].as_i64();
        let ids = case["rows"].as_array().unwrap().iter().map(|row| row.get("chatId").cloned()).collect::<Vec<_>>();
        let mode = match case["mode"].as_str().unwrap() {
            "editinput" => LuaMode::Script(ScriptMode::EditInput), "editoutput" => LuaMode::Script(ScriptMode::EditOutput),
            "editdisplay" => LuaMode::Script(ScriptMode::EditDisplay), "editRequest" => LuaMode::EditRequest,
            "editprocess" => LuaMode::Script(ScriptMode::EditProcess), name => panic!("unknown edit mode {name}"),
        };
        let mut reported: Vec<Effect> = Vec::new();
        let mut calls = Vec::new();
        for _ in 0..case["calls"].as_u64().unwrap() {
            let previous=reported.len();
            let reloaded=case["persistence"]=="json-roundtrip";
            let view = LuaView { effects: reported.iter().map(|effect| match effect {
                Effect::ChatVariable {name,value} if reloaded=>Effect::ChatVariable {name:name.copy(&budget).unwrap(),value:canonical_variable(value,&budget)},
                effect=>copy_effect(effect,&budget),
            }).collect(), locals: Vec::new() };
            let request = HostRequest::Lua { trigger: LuaTrigger::Edit { index }, mode, payload: content(case, &budget), view };
            let reply = answer(&mut host, request, Context { owner: "char-b", triggers: &triggers, records: Records::Snapshot(&records),
                cancellation: &Cancellation::default(), budget: &budget });
            let data = match (case["decline"].as_str(), reply) {
                (Some(label), Err(failure)) if failure.reason == label => return Ok(()),
                (None, Ok(HostReply::Lua(LuaReply { value, effects, stop_sending: false }))) => { reported.extend(effects); value }
                (label, reply) => return Err(format!("reply {reply:?}, expected {label:?}")),
            };
            // The rows and variables the effects so far give.
            let mut rows = json::parse_json(&case["rows"].to_string(), &budget).unwrap();
            let mut state = case["scriptstate"].as_object().unwrap().iter().map(|(key, value)| (key.clone(), stored_tag(value, &budget))).collect::<Vec<_>>();
            for (effect_index,effect) in reported.iter().enumerate() {
                match effect {
                    Effect::Message(edit) => edit_messages(&mut rows, edit, &budget).map_err(|error| format!("effect {edit:?}: {error:?}"))?,
                    Effect::ChatVariable { name, value } => {
                        let key = format!("${}", name.as_unicode().unwrap());
                        state.retain(|(existing, _)| *existing != key);
                        if reloaded&&effect_index<previous {
                            let value=canonical_variable(value,&budget);
                            if !matches!(value,Value::Undefined){state.push((key,tag(&value,&budget)));}
                        } else {state.push((key,tag(value,&budget)));}
                    }
                    effect => return Err(format!("effect {effect:?}")),
                }
            }
            state.sort_by(|left, right| left.0.encode_utf16().cmp(right.0.encode_utf16()));
            let rows: Json = serde_json::from_str(json::stringify(&rows, &budget).unwrap().unwrap().as_unicode().unwrap()).unwrap();
            let mut observation=json!({
                "data": if case["mode"] == "editRequest" { canonical_request(&data, &budget)? } else { tag(&data, &budget) },
                "scriptstate": state.iter().map(|(key, value)| json!([key, value])).collect::<Vec<_>>(),
                "messages": rows.as_array().unwrap().iter().map(|row| stored_message(row, &ids, &budget)).collect::<Vec<_>>(),
            });
            if case.get("authorNote").is_some() { observation["authorNote"] = author_note_tags(&records.conversation, &budget); }
            if reloaded{
                let mut durable=case["scriptstate"].clone();
                for effect in &reported{
                    if let Effect::ChatVariable {name,value}=effect{
                        let key=format!("${}",name.as_unicode().unwrap());
                        match canonical_variable_json(value,&budget){
                            Some(value)=>{durable.as_object_mut().unwrap().insert(key,value);}
                            None=>{durable.as_object_mut().unwrap().remove(&key);}
                        }
                    }
                }
                observation["storedScriptstate"]=variable_tags(&durable,&budget);
            }
            calls.push(observation);
        }
        let actual = json!({ "calls": calls });
        if actual == *expected { Ok(()) } else { Err(format!("\n  actual   {actual}\n  expected {expected}")) }
    });
}

fn trigger_request(code: &str, entry: &str, low_level: bool, deadline: LuaDeadline, view: LuaView, budget: &Budget) -> HostRequest {
    let call = LuaCall { code: Text::from_str(code, budget).unwrap(), entry: Text::from_str(entry, budget).unwrap(), low_level, deadline };
    HostRequest::Lua { trigger: LuaTrigger::Effect { trigger: 0, effect: 0, call }, mode: LuaMode::Trigger(TriggerMode::Start),
        payload: Value::Undefined, view }
}

fn run_trigger(host: &mut LuaHost, records: &Arc<ConversationSnapshot>, request: HostRequest, budget: &Budget) -> Result<HostReply, EditFailure> {
    answer(host, request, Context { owner: "char-b", triggers: &[], records: Records::Snapshot(records), cancellation: &Cancellation::default(), budget })
}

fn one_row() -> Arc<ConversationSnapshot> { snapshot(&json!([{ "role": "user", "data": "hello", "chatId": "m1" }]), &json!({})) }

fn text_of(value: &Value) -> Option<&str> { if let Value::Text(text) = value { text.as_unicode() } else { None } }

fn variable<'a>(effect: &'a Effect) -> Option<(&'a str, &'a Value)> {
    if let Effect::ChatVariable { name, value } = effect { Some((name.as_unicode()?, value)) } else { None }
}

// `runScripted` returns `res`; `stopChat()` or `res === false` sets the stop, which an error after `stopChat` keeps.
#[test]
fn trigger_replies_carry_the_result_effects_and_stop() {
    let budget = budget();
    let records = one_row();
    let mut host = host();
    let mut reply = |code: &str| run_trigger(&mut host, &records, trigger_request(code, "start", false, LuaDeadline::Listener, LuaView::default(), &budget), &budget);
    let returned = |reply: Result<HostReply, EditFailure>| match reply {
        Ok(HostReply::Lua(LuaReply { value, effects, stop_sending })) => (value, effects, stop_sending),
        reply => panic!("{reply:?}"),
    };
    let (value, effects, stop) = returned(reply("function onStart(id) setChatVar(id, 'k', 'v') return false end"));
    assert!(matches!(value, Value::Bool(false)) && stop, "{value:?}");
    assert!(matches!(effects.as_slice(), [effect] if matches!(variable(effect), Some(("k", value)) if text_of(value) == Some("v"))), "{effects:?}");
    let (value, effects, stop) = returned(reply("function onStart(id) stopChat(id) return 'kept' end"));
    assert!(text_of(&value) == Some("kept") && effects.is_empty() && stop, "{value:?}");
    let (value, _, stop) = returned(reply("function onStart(id) stopChat('other') return true end"));
    assert!(matches!(value, Value::Bool(true)) && !stop, "{value:?}");
    // A handler error is caught and logged: the call returns normally with the writes and the stop made before it.
    let (value, effects, stop) = returned(reply("function onStart(id) setChatVar(id, 'k', 'v') stopChat(id) error('boom') end"));
    assert!(matches!(value, Value::Undefined) && stop && effects.len() == 1, "{value:?} {effects:?}");
    let (value, effects, stop) = returned(reply("function onStart(id) error('boom') end"));
    assert!(matches!(value, Value::Undefined) && effects.is_empty() && !stop, "{value:?}");
    let (value, _, stop) = returned(reply("x = 1"));
    assert!(matches!(value, Value::Undefined) && !stop, "{value:?}");
    let (value, _, _) = returned(reply("function onStart(id) return 2.5 end"));
    assert!(matches!(value, Value::Number(number) if number == 2.5), "{value:?}");
    for code in ["error('init failed')", "function onStart("] {
        let failed = reply(code);
        assert!(matches!(&failed, Ok(HostReply::Failed { message }) if message.len_units() > 0), "{failed:?}");
    }
    let failed = reply("error('init failed')");
    assert!(matches!(&failed, Ok(HostReply::Failed { message }) if message.as_unicode().is_some_and(|text| text.contains("init failed"))), "{failed:?}");
}

// A timeout is logged and `res` stays undefined; the writes before it stay, and the engine is not reused.
#[test]
fn a_trigger_timeout_returns_undefined_and_keeps_its_writes() {
    let budget = budget();
    let records = one_row();
    let mut host = timed(Duration::from_millis(250));
    let code = "count = 0 function onStart(id) count = count + 1 setChatVar(id, 'k', tostring(count)) while true do end end";
    for _ in 0..2 {
        let reply = run_trigger(&mut host, &records, trigger_request(code, "start", false, LuaDeadline::Listener, LuaView::default(), &budget), &budget);
        assert!(matches!(&reply, Ok(HostReply::Lua(LuaReply { value: Value::Undefined, effects, stop_sending: false }))
            if matches!(effects.as_slice(), [effect] if matches!(variable(effect), Some(("k", value)) if text_of(value) == Some("1")))), "{reply:?}");
    }
}

// `runScripted`'s switch: the event handlers, the edit listeners through `callListenMain`, and any other name as a global.
// The mode string and the deadline class key the engine with the code.
#[test]
fn trigger_entries_pick_the_function_runscripted_calls() {
    let budget = budget();
    let records = one_row();
    let mut host = host();
    let mut value = |code: &str, entry: &str, deadline: LuaDeadline| {
        match run_trigger(&mut host, &records, trigger_request(code, entry, false, deadline, LuaView::default(), &budget), &budget) {
            Ok(HostReply::Lua(LuaReply { value, .. })) => value,
            reply => panic!("{entry}: {reply:?}"),
        }
    };
    let handlers = "function onStart(id) return 'start' end function onOutput(id) return 'output' end function onInput(id) return 'input' end
        function onButtonClick(id, data) return type(data) .. ':' .. data end function onFormSubmit(id, data, meta) return data .. '|' .. meta end
        function custom(id) return 'custom' end";
    for (entry, expected) in [("start", "start"), ("output", "output"), ("input", "input"), ("onButtonClick", "string:"), ("onFormSubmit", "|{}"),
        ("custom", "custom")] {
        assert_eq!(text_of(&value(handlers, entry, LuaDeadline::Listener)), Some(expected), "{entry}");
    }
    let listeners = "listenEdit('editOutput', function(id, value) return value .. 'x' end) listenEdit('editDisplay', function(id, value) return value .. 'y' end)";
    assert_eq!(text_of(&value(listeners, "editOutput", LuaDeadline::Listener)), Some("x"));
    assert_eq!(text_of(&value(listeners, "editDisplay", LuaDeadline::Listener)), Some("y"));
    let counting = "count = 0 function onStart(id) count = count + 1 return count end function custom(id) count = count + 1 return count end";
    let counts = [("start", LuaDeadline::Listener), ("start", LuaDeadline::Listener), ("custom", LuaDeadline::Listener), ("start", LuaDeadline::UserStarted)]
        .map(|(entry, deadline)| match value(counting, entry, deadline) { Value::Number(count) => count, value => panic!("{value:?}") });
    assert_eq!(counts, [1.0, 2.0, 1.0, 1.0]);
}

// `getVar` reads the trigger locals first, then this request's writes and the view's, then the stored chat; `setVar` writes
// a local of that name, and TS stores a non-string as given.
#[test]
fn trigger_lua_reads_locals_and_the_view_and_reports_writes_as_effects() {
    let budget = budget();
    let records = snapshot(&json!([{ "role": "user", "data": "hello", "chatId": "m1" }]), &json!({ "$shared": "stored", "$plain": "stored", "$list": [1, false] }));
    let mut host = host();
    let text = |value: &str| Text::from_str(value, &budget).unwrap();
    let view = LuaView { effects: vec![Effect::ChatVariable { name: text("shared"), value: Value::Text(text("view")) }],
        locals: vec![(text("loc"), Value::Text(text("local")))] };
    let code = "function onStart(id)
        local before = table.concat({ getChatVar(id, 'loc'), getChatVar(id, 'shared'), getChatVar(id, 'plain'), getChatVar(id, 'list'), getChatVar(id, 'none') }, '|')
        setChatVar(id, 'loc', 'changed') setChatVar(id, 'n', 7) setChatVar(id, 'shared', 'view')
        return before .. '|' .. getChatVar(id, 'loc') .. '|' .. math.type(getChatVar(id, 'n'))
    end";
    let reply = run_trigger(&mut host, &records, trigger_request(code, "start", false, LuaDeadline::Listener, view, &budget), &budget);
    let Ok(HostReply::Lua(LuaReply { value, effects, stop_sending: false })) = reply else { panic!("{reply:?}") };
    assert_eq!(text_of(&value), Some("local|view|stored|1,false|null|changed|integer"));
    // Changed writes replay through the owner's setVar, including locals; the unchanged shared value emits no effect.
    assert!(matches!(effects.as_slice(), [local, number]
        if matches!(variable(local), Some(("loc", value)) if text_of(value) == Some("changed"))
            && matches!(variable(number), Some(("n", Value::Number(number))) if *number == 7.0)), "{effects:?}");
    for (ending,reason) in [
        ("return true".to_owned(),None),
        ("error('boom')".to_owned(),None),
        ("cbs('unsupported')".to_owned(),Some("lua-host:cbs")),
        (format!("{TEST_PANIC}()"),Some("lua-host-panic")),
    ] {
        let view=LuaView {effects:vec![],locals:vec![(text("loc"),Value::Text(text("local")))]};
        let code=format!("function onStart(id)setChatVar(id,'loc','first');setChat(id,0,'ordered');setChatVar(id,'loc','second');setChatVar(id,'marker','ready');{ending} end");
        let reply=run_trigger(&mut host,&records,trigger_request(&code,"start",false,LuaDeadline::Listener,view,&budget),&budget);
        let effects=match reply {
            Ok(HostReply::Lua(LuaReply {value,effects,stop_sending:false}))=>{
                assert!(reason.is_none(),"{ending}");
                if ending.starts_with("return") {assert!(matches!(value,Value::Bool(true)));}
                else {assert!(matches!(value,Value::Undefined));}
                effects
            },
            Err(failure)=>{assert_eq!(Some(failure.reason.as_str()),reason,"{ending}");failure.saved.effects},
            reply=>panic!("{ending}: {reply:?}"),
        };
        assert!(matches!(effects.as_slice(),[
            first,Effect::Message(MessageEdit::SetData {index:0.0,data:Value::Text(data)}),second,marker,
        ] if matches!(variable(first),Some(("loc",value)) if text_of(value)==Some("first"))
            && data.as_unicode()==Some("ordered")
            && matches!(variable(second),Some(("loc",value)) if text_of(value)==Some("second"))
            && matches!(variable(marker),Some(("marker",value)) if text_of(value)==Some("ready"))),"{ending}: {effects:?}");
    }

}

// A `ScriptingLowLevelIds` name declines only for a call holding a low-level key; without one TS refuses it.
#[test]
fn low_level_names_decline_only_with_a_low_level_key() {
    let budget = budget();
    let records = one_row();
    let mut host = host();
    for (call, name) in [("similarity(id, 'a', 'b')", "similarity"), ("LLMMain(id, '[]')", "LLMMain"), ("request(id, 'x')", "request")] {
        let code = format!("function onStart(id) {call} return 'refused' end");
        let refused = run_trigger(&mut host, &records, trigger_request(&code, "start", false, LuaDeadline::Listener, LuaView::default(), &budget), &budget);
        assert!(matches!(&refused, Ok(HostReply::Lua(LuaReply { value, .. })) if text_of(value) == Some("refused")), "{name}: {refused:?}");
        let declined = run_trigger(&mut host, &records, trigger_request(&code, "start", true, LuaDeadline::Listener, LuaView::default(), &budget), &budget);
        assert!(matches!(&declined, Err(failure) if failure.reason == format!("lua-host:{name}")), "{name}: {declined:?}");
    }
    let code = "function onStart(id) alertNormal('other', 'x') return 'refused' end";
    let refused = run_trigger(&mut host, &records, trigger_request(code, "start", false, LuaDeadline::Listener, LuaView::default(), &budget), &budget);
    assert!(matches!(&refused, Ok(HostReply::Lua(LuaReply { value, .. })) if text_of(value) == Some("refused")), "{refused:?}");
    let code = "function onStart(id) alertNormal(id, 'x') return 'refused' end";
    let declined = run_trigger(&mut host, &records, trigger_request(code, "start", false, LuaDeadline::Listener, LuaView::default(), &budget), &budget);
    assert!(matches!(&declined, Err(failure) if failure.reason == "lua-host:alertNormal"), "{declined:?}");
}

// Card code starts with every host name registered and no `hostAwait`. `string.dump` and any collector option other
// than a full collection decline the request even under `pcall`, as the Wasmoon profile does.
#[test]
fn card_code_meets_the_whole_host_surface_and_the_restricted_library() {
    let budget = budget();
    let records = one_row();
    let mut host = host();
    let names = HOST_API.iter().map(|(name, _, _)| format!("'{name}'")).collect::<Vec<_>>().join(", ");
    let mut call = |body: &str| {
        let code = format!("local missing = {{}} for _, name in ipairs({{ {names} }}) do if type(_G[name]) ~= 'function' then missing[#missing + 1] = name end end
            surface = table.concat(missing, ',') .. '|' .. tostring(hostAwait == nil)
            function onStart(id) {body} end");
        run_trigger(&mut host, &records, trigger_request(&code, "start", true, LuaDeadline::Listener, LuaView::default(), &budget), &budget)
    };
    let reply = call("return table.concat({ surface, tostring(pcall(collectgarbage)), tostring(pcall(collectgarbage, 'collect')) }, '|')");
    assert!(matches!(&reply, Ok(HostReply::Lua(LuaReply { value, .. })) if text_of(value) == Some("|true|true|true")), "{reply:?}");
    for (body, label) in [("pcall(string.dump, onStart) return 'continued'", "lua-std:string.dump"),
        ("pcall(collectgarbage, 'stop') return 'continued'", "lua-std:collectgarbage"),
        ("pcall(collectgarbage, 'count') return 'continued'", "lua-std:collectgarbage")] {
        let reply = call(body);
        assert!(matches!(&reply, Err(failure) if failure.reason == label), "{body}: {reply:?}");
    }
}

// A panic in host code fails the request whether card code catches it or not, and the next request gets a new engine.
#[test]
fn a_host_panic_fails_the_request_and_the_next_request_gets_a_fresh_engine() {
    let budget = budget();
    let records = one_row();
    let mut host = host();
    let code = format!("count = 0 function onStart(id)
        count = count + 1
        if getChatVar(id, 'boom') == 'pcall' then setChatVar(id, 'before', '1') pcall({TEST_PANIC}) end
        if getChatVar(id, 'boom') == 'coroutine' then coroutine.resume(coroutine.create({TEST_PANIC})) end
        if getChatVar(id, 'boom') == 'direct' then {TEST_PANIC}() end
        return count
    end");
    let text = |value: &str| Text::from_str(value, &budget).unwrap();
    let mut call = |boom: Option<&str>| {
        let effects = boom.map(|boom| vec![Effect::ChatVariable { name: text("boom"), value: Value::Text(text(boom)) }]).unwrap_or_default();
        run_trigger(&mut host, &records, trigger_request(&code, "start", false, LuaDeadline::Listener, LuaView { effects, locals: Vec::new() }, &budget), &budget)
    };
    let count = |reply: Result<HostReply, EditFailure>| match reply {
        Ok(HostReply::Lua(LuaReply { value: Value::Number(count), .. })) => count,
        reply => panic!("{reply:?}"),
    };
    assert_eq!([count(call(None)), count(call(None))], [1.0, 2.0]);
    let panicked = call(Some("pcall"));
    assert!(matches!(&panicked, Err(failure) if failure.reason == "lua-host-panic"
        && failure.edits == [Edit::Variable { key: "before".into(), value: "1".into() }]), "{panicked:?}");
    assert_eq!(count(call(None)), 1.0);
    for boom in ["coroutine", "direct"] {
        let panicked = call(Some(boom));
        assert!(matches!(&panicked, Err(failure) if failure.reason == "lua-host-panic"), "{boom}: {panicked:?}");
        assert_eq!(count(call(None)), 1.0, "{boom}");
    }
}

