#[test]
fn author_note_reads_resolve_links_without_materializing_snapshot_or_store_records() {
    let link = json!({"id":"p", "fingerprint":"2:cb31c4b8"});
    let presets = json!([{"id":"p", "name":"Synthetic preset", "text":"current note"}]);
    let cases = [
        (json!({"note":"😀", "link":link, "presets":presets}), "current note"),
        (json!({"note":"😀", "link":link, "presets":[]}), ""),
        (json!({"note":"😀", "link":link}), ""),
        (json!({"note":"😀", "link":link, "presets":null}), ""),
        (json!({"note":"😀", "link":link, "presets":[{"id":"p", "text":"invalid preset"}]}), ""),
        (json!({"note":"manual note", "link":link, "presets":{}}), "manual note"),
        (json!({"note":"manual note", "link":link, "presets":presets}), "manual note"),
        (json!({"note":"raw note", "link":{"id":7,"fingerprint":"invalid"}, "presets":presets}), "raw note"),
        (json!({"note":null}), ""),
        (json!({}), ""),
        (json!({"link":{"id":"p","fingerprint":"0:811c9dc5"}, "presets":presets}), "current note"),
        (json!({"note":null, "link":{"id":"p","fingerprint":"0:811c9dc5"}, "presets":presets}), "current note"),
        (json!({"note":false, "link":{"id":"p","fingerprint":"0:811c9dc5"}, "presets":presets}), "current note"),

    ];
    for (index, (note, expected)) in cases.into_iter().enumerate() {
        let budget = budget();
        let mut records = ConversationSnapshot { character: json!({}), conversation: json!({}), messages: vec![], root: json!({}) };
        for (field, input) in [("note", "note"), ("authorNotePreset", "link")] {
            if let Some(value) = note.get(input) { records.conversation[field] = value.clone(); }
        }
        if let Some(value) = note.get("presets") { records.root["authorNotePresets"] = value.clone(); }
        let records = Arc::new(records);
        let before = records.conversation.clone();
        let request = || trigger_request("function onStart(id) return getAuthorsNote(id) end", "start", false,
            LuaDeadline::Listener, LuaView::default(), &budget);
        let overlay = run_trigger(&mut host(), &records, request(), &budget);
        let (_directory, store) = fixture_records(&json!([]), &json!({}), None, Some(&note));
        let pool = AccessPool::new(settings()).unwrap(); let access = scope(&store, &pool);
        let raw = conversation(&store);
        let revision = store.borrow().revision().unwrap();
        let stored = answer(&mut host(), request(), Context { owner:"char-b", triggers:&[], records:Records::Store { access:&access,store:&store },
            cancellation:&Cancellation::default(), budget:&budget });
        for reply in [overlay, stored] {
            let HostReply::Lua(reply) = reply.unwrap() else { panic!("case {index}: Lua reply") };
            assert_eq!(text_of(&reply.value), Some(expected), "case {index}");
            assert!(reply.effects.is_empty(), "case {index}: {:?}", reply.effects);
        }
        commit(&access, &store);
        assert_eq!(records.conversation, before, "case {index}: snapshot remained raw");
        assert_eq!(conversation(&store), raw, "case {index}: stored records remained raw");
        assert_eq!(store.borrow().revision().unwrap(), revision, "case {index}: read did not write");
    }
}

#[test]
fn detached_author_notes_skip_oversized_presets_and_charged_reads_release_their_values() {
    use super::lua_view::{author_note, record_value, Overlay};
    for (raw, link, expected) in [("manual", Json::Null, Some("manual")),
        ("manual", json!({"id":"p","fingerprint":"2:cb31c4b8"}), Some("manual")),
        ("😀", json!({"id":"p","fingerprint":"2:cb31c4b8"}), None)] {
        let budget = Budget::new(risunest_ir::Limits {max_owned_bytes:16<<10,..ir_limits()},Default::default()).unwrap();
        let note = json!({"note":raw,"link":link,"presets":[{"id":"p","name":"Synthetic preset","text":"x".repeat(64<<10)}]});
        let records = Arc::new(ConversationSnapshot { character:json!({"name":"charged name"}), messages:vec![],
            conversation:json!({"note":raw,"authorNotePreset":link}), root:json!({"authorNotePresets":note["presets"]}) });
        let overlay = Overlay::new(records,&LuaView::default(),true,&budget).unwrap();
        let (_directory,store) = fixture_records(&json!([]),&json!({}),None,Some(&note));
        let pool = AccessPool::new(settings()).unwrap(); let access = scope(&store,&pool);
        let stored = StoreSource::new(access.clone(),store.clone(),budget.clone());
        stored.begin().unwrap();
        let before = budget.owned_bytes();
        for source in [&overlay as &dyn Conversation,&stored as &dyn Conversation] {
            match (expected, author_note(source,&budget)) {
                (Some(expected), Ok(value)) => {
                    assert_eq!(text_of(&value),Some(expected));
                    assert!(budget.owned_bytes()>before);
                    drop(value);
                }
                (None, Err(error)) => assert!(error.contains("Limit"),"{error}"),
                (expected, result) => panic!("expected {expected:?}, got {result:?}"),
            }
            assert_eq!(budget.owned_bytes(),before);
            let value = record_value(source,"character","name",&budget).unwrap().unwrap();
            assert!(matches!(value,Value::Text(_)));
            assert!(budget.owned_bytes()>before);
            drop(value);
            assert_eq!(budget.owned_bytes(),before);
        }
        stored.end().unwrap();
        commit(&access,&store);
        assert_eq!(conversation(&store)["note"],raw);
    }
}

#[test]
fn scalar_history_outputs_retain_both_the_ir_value_and_utf8_until_the_caller_releases_them() {
    use super::lua_scalar_adapter::{host as scalar_host, Binding, Permissions};
    use super::lua_view::Overlay;
    let budget = budget();
    let records = snapshot(&json!([{"role":"user","data":"x".repeat(1024),"chatId":"m"}]),&json!({}));
    let source:Rc<dyn Conversation> = Rc::new(Overlay::new(records,&LuaView::default(),true,&budget).unwrap());
    let binding = Rc::new(RefCell::new(Some(Binding {source:source.clone(),key:"key".into(),permissions:Permissions::Safe,budget:budget.clone()})));
    for (name,field,expected) in [("getChatData","data","x".repeat(1024)),("getChatRole","role","user".into())] {
        let before = budget.owned_bytes();
        let value = source.message_value(0.0,field,&budget).unwrap().unwrap();
        let ir_bytes = budget.owned_bytes()-before;
        drop(value);
        let output = scalar_host(&binding,name,vec![risunest_native_lua_experimental::Scalar::String("key".into()),
            risunest_native_lua_experimental::Scalar::Number(0.0)],1<<20,true).unwrap();
        assert_eq!(output.as_ref(),&risunest_native_lua_experimental::ScalarReturn::One(risunest_native_lua_experimental::Scalar::String(expected.clone())));
        assert!(budget.owned_bytes()>=before+ir_bytes+expected.len());
        drop(output);
        assert_eq!(budget.owned_bytes(),before);
    }
}

#[test]
fn malformed_author_note_lists_are_catchable_and_preserve_writes_before_and_after_the_read() {
    let budget = budget();
    let note = json!({"note":"😀","link":{"id":"p","fingerprint":"2:cb31c4b8"},"presets":{}});
    let records = Arc::new(ConversationSnapshot { character:json!({}), messages:vec![],
        conversation:json!({"note":note["note"],"authorNotePreset":note["link"]}), root:json!({"authorNotePresets":{}}) });
    let code = "function onStart(id) setChatVar(id,'before','kept'); local ok=pcall(getAuthorsNote,id); setChatVar(id,'after','kept'); return tostring(ok)..'|'..getChatVar(id,'before')..'|'..getChatVar(id,'after') end";
    let request = || trigger_request(code,"start",false,LuaDeadline::Listener,LuaView::default(),&budget);
    let overlay = run_trigger(&mut host(),&records,request(),&budget);
    let (_directory,store) = fixture_records(&json!([]),&json!({}),None,Some(&note));
    let pool = AccessPool::new(settings()).unwrap(); let access = scope(&store,&pool);
    let stored = answer(&mut host(),request(),Context {owner:"char-b",triggers:&[],records:Records::Store {access:&access,store:&store},
        cancellation:&Cancellation::default(),budget:&budget});
    for reply in [overlay,stored] {
        let HostReply::Lua(reply) = reply.unwrap() else {panic!("Lua reply")};
        assert_eq!(text_of(&reply.value),Some("false|kept|kept"));
        let writes = reply.effects.iter().map(|effect| { let (name,value)=variable(effect).unwrap(); (name,text_of(value).unwrap()) }).collect::<Vec<_>>();
        assert_eq!(writes,[("before","kept"),("after","kept")]);
    }
    commit(&access,&store);
    let stored = conversation(&store);
    assert_eq!(stored["scriptstate"],json!({"$before":"kept","$after":"kept"}));
    assert_eq!((stored["note"].clone(),stored["authorNotePreset"].clone()),(note["note"].clone(),note["link"].clone()));
    assert_eq!(records.conversation["note"],note["note"]);
}

#[test]
fn author_note_reads_follow_prior_view_note_and_link_assignments_and_the_persona_processor() {
    use risunest_cbs_experimental::cbs::processor::{Character,Chat,Database,Processor,Snapshot,Source};
    use risunest_ir::rng::Tape;
    use super::lua_view::PersonaProcessor;
    for (raw, view_note, view_link, expected) in [
        ("😀", "manual note", None, "manual note"),
        ("manual note", "😀", None, "current note"),
        ("😀", "😀", Some(json!({"id":"q", "fingerprint":"2:cb31c4b8"})), "other note"),
    ] {
        let budget = budget();
        let records = Arc::new(ConversationSnapshot { character:json!({}), messages:vec![],
            conversation:json!({"note":raw,"authorNotePreset":{"id":"p","fingerprint":"2:cb31c4b8"}}),
            root:json!({"authorNotePresets":[{"id":"p","name":"Synthetic preset","text":"current note"},
                {"id":"q","name":"Other synthetic preset","text":"other note"}], "personaPrompt":"{{authornote}}"}) });
        let text = |value| Text::from_str(value, &budget).unwrap();
        let mut effects = vec![Effect::ChatField { field:text("note"), value:Value::Text(text(view_note)) }];
        let mut effective_chat = records.conversation.clone();
        effective_chat["note"] = view_note.into();
        if let Some(link) = view_link {
            effects.push(Effect::ChatField { field:text("authorNotePreset"), value:json::parse_json(&link.to_string(), &budget).unwrap() });
            effective_chat["authorNotePreset"] = link;
        }
        // The capability starts after the view, while the conversation snapshot keeps its raw pre-view fields.
        let root = super::lua_view::ir_value(&records.root, &budget).unwrap();
        let chat = super::lua_view::ir_value(&effective_chat, &budget).unwrap();
        let binding = risunest_records::author_note::Binding::from_records(&root, &chat, &budget).unwrap();
        let note = risunest_records::author_note::resolve(binding.as_ref(), chat.get(b"note", &budget).unwrap(), &budget).unwrap()
            .map(|value| copy_value(value, &budget).unwrap());
        let parser = Snapshot { source:Source::Database(Box::new(Database { character:Some(Character { chat:Chat { note,
            author_note_binding:binding, ..Chat::default() }, ..Character::default() }), ..Database::default() })), ..Snapshot::default() };
        let processor:PersonaProcessor = Rc::new(RefCell::new(Box::new(Processor::new(parser, Tape::new(Vec::new())))));
        let request = trigger_request("function onStart(id) return getAuthorsNote(id)..'|'..getPersonaDescription(id) end", "start", false,
            LuaDeadline::Listener, LuaView { effects, locals:vec![] }, &budget);
        let HostReply::Lua(reply) = answer(&mut host(), request, Context {owner:"char-b",triggers:&[],
            records:Records::ProcessedSnapshot(&records,&processor),cancellation:&Cancellation::default(),budget:&budget}).unwrap() else {panic!("Lua reply")};
        assert_eq!(text_of(&reply.value), Some(format!("{expected}|{expected}").as_str()));
        assert!(reply.effects.is_empty());
        assert_eq!(records.conversation["note"], raw);
        assert_eq!(records.conversation["authorNotePreset"]["id"], "p");
    }
}

#[test]
fn d5_record_reads_follow_the_view_and_the_typescript_key_checks() {
    let budget = budget();
    let records = Arc::new(ConversationSnapshot {
        character: json!({"name":"stored", "desc":"old description", "firstMessage":"old greeting", "defaultVariables":"fallback=old"}),
        conversation: json!({"note":"old note", "scriptstate":{"$discarded":"old"}, "GLGlobalVariables":{"g":"local"}}),
        messages: vec![json!({"role":"user","data":"user tail","chatId":"u"}), json!({"role":"char","data":"char tail","chatId":"c"})],
        root: json!({"username":"root user", "globalChatVariables":{"g":"global","fallback":"global fallback","object":{"a":1},"array":[2,false],"7":"number key","true":"boolean key","null":"null key","undefined":"missing key"},
            "personas":[{"id":"연결😀","name":"bound user","personaPrompt":"bound prompt"}]}),
    });
    let text = |value| Text::from_str(value, &budget).unwrap();
    let field = |name, value| Effect::CharacterField { field: text(name), value: text(value) };
    let view = LuaView { effects: vec![
        field("name", "first name"), field("name", "visible name"), field("desc", "visible description"),
        field("firstMessage", "visible greeting"), field("defaultVariables", "fallback=visible default"),
        Effect::ChatVariable { name: text("discarded"), value: Value::Text(text("earlier")) },
        Effect::ChatField { field: text("scriptstate"), value: json::parse_json("{}", &budget).unwrap() },
        Effect::ChatField { field: text("note"), value: Value::Text(text("visible note")) },
        Effect::ChatField { field: text("bindedPersona"), value: Value::Text(text("연결😀")) },
        Effect::ChatField { field: text("GLGlobalVariables"), value: json::parse_json(r#"{"g":"null"}"#, &budget).unwrap() },
    ], locals: vec![] };
    let code = r#"function onStart(id)
        assert(getDescription('wrong') == nil)
        assert(getChatVar(id,'discarded') == 'null')
        assert(getChatVar(id,'fallback') == 'visible default')
        return table.concat({getName('wrong'),getDescription(id),getCharacterFirstMessage(id),getPersonaName(id),getAuthorsNote(id),
            getCharacterLastMessage(id),getUserLastMessage(id),getGlobalVar('wrong','g'),getGlobalVar(id,'fallback'),getGlobalVar(id,'absent')}, '|')
    end"#;
    let request = trigger_request(code, "start", false, LuaDeadline::Listener, view, &budget);
    let HostReply::Lua(reply) = run_trigger(&mut host(), &records, request, &budget).unwrap() else { panic!("Lua reply") };
    assert_eq!(text_of(&reply.value), Some("visible name|visible description|visible greeting|bound user|visible note|char tail|user tail|global|global fallback|null"));
    assert!(reply.effects.is_empty());

    let view = LuaView { effects: vec![], locals: vec![] };
    let request = trigger_request("listenEdit('editDisplay',function(id,v) assert(getDescription(id)==nil); return getName(id) end)",
        "editDisplay", false, LuaDeadline::Listener, view, &budget);
    let HostReply::Lua(reply) = run_trigger(&mut host(), &records, request, &budget).unwrap() else { panic!("Lua reply") };
    assert_eq!(text_of(&reply.value), Some("stored"));

    let view=LuaView {effects:vec![
        Effect::Message(MessageEdit::SetData {index:0.0,data:json::parse_json("[3,false,null]",&budget).unwrap()}),
        Effect::Message(MessageEdit::SetData {index:1.0,data:json::parse_json(r#"{"nested":{"a":1}}"#,&budget).unwrap()}),
    ],locals:vec![]};
    let code=r#"function onStart(id)
        local character=getCharacterLastMessage(id)
        local user=getUserLastMessage(id)
        assert(type(character)=='table' and character.nested.a==1)
        assert(type(user)=='table' and user[1]==3 and user[2]==false and user[3]==null)
        local object=getGlobalVar('wrong','object')
        local array=getGlobalVar('wrong','array')
        assert(object.a==1 and array[1]==2 and array[2]==false)
        object.a=9
        assert(getGlobalVar(id,'object').a==1)
        assert(getGlobalVar(id,7)=='number key' and getGlobalVar(id,true)=='boolean key')
        assert(getGlobalVar(id,nil)=='null key' and getGlobalVar(id)=='missing key')
        return true
    end"#;
    let request=trigger_request(code,"start",false,LuaDeadline::Listener,view,&budget);
    let HostReply::Lua(reply)=run_trigger(&mut host(),&records,request,&budget).unwrap() else{panic!("Lua reply")};
    assert!(matches!(reply.value,Value::Bool(true)));
    assert!(reply.effects.is_empty());
}

#[test]
fn cut_and_add_chat_preserve_metadata_and_report_the_actual_message_edits() {
    let budget = budget();
    let rows = json!([
        {"role":"char","data":"first","chatId":"m1","future":{"kept":true}},
        {"role":"user","data":"second","chatId":"m2"},
        {"role":"char","data":"third","chatId":"m3"}
    ]);
    let code = r#"function onStart(id)
        cutChat('wrong',0,0); addChat('wrong','user','refused')
        cutChat(id,-2)
        addChat(id,'narrator',nil)
        assert(getChatLength(id)==3 and getCharacterLastMessage(id)=='')
        cutChat(id,0,1)
        assert(getUserLastMessage(id)=='second')
        cutChat(id,0,0)
        assert(getUserLastMessage(id)=='' and getCharacterLastMessage(id)=='greeting')
        addChat(id,'user','last user')
        return getFullChatMain(id)
    end"#;
    let records = Arc::new(ConversationSnapshot { character: json!({"firstMessage":"greeting"}),
        conversation: json!({}), messages: rows.as_array().unwrap().clone(), root: json!({}) });
    let request = trigger_request(code, "start", false, LuaDeadline::Listener, LuaView::default(), &budget);
    let HostReply::Lua(reply) = run_trigger(&mut host(), &records, request, &budget).unwrap() else { panic!("Lua reply") };
    assert_eq!(reply.effects.len(), 5);
    assert!(matches!(reply.effects[0], Effect::Message(MessageEdit::Cut { start: -2.0, end: None })));
    assert!(matches!(reply.effects[1], Effect::Message(MessageEdit::Append { role: MessageRole::Char, .. })));
    assert!(matches!(reply.effects[4], Effect::Message(MessageEdit::Append { role: MessageRole::User, .. })));
    let result: Json = serde_json::from_str(text_of(&reply.value).unwrap()).unwrap();
    assert_eq!(result[0]["data"], "last user");
    assert!(is_uuid_v4(result[0]["chatId"].as_str().unwrap()));

    // The existing store source uses the same cuts while retaining fields of surviving rows.
    let (_directory, store) = fixture(&rows, &json!({}));
    let pool = AccessPool::new(settings()).unwrap();
    let access = scope(&store, &pool);
    let triggers = ["listenEdit('editOutput',function(id,v) cutChat(id,0,-1); addChat(id,'user','appended'); return v end)".to_owned()];
    let outcome = host().run(Batch { owner:"char-b", mode:EditMode::Output, content:Value::Text(Text::from_str("content",&budget).unwrap()), index:None,
        triggers:&triggers, source:&source(&access,&store,&budget), cancellation:&Cancellation::default(), budget:&budget }).unwrap();
    assert_eq!(outcome.status, Status::Completed);
    commit(&access, &store);
    let stored = conversation(&store);
    assert_eq!(stored["message"][0], rows[0]);
    assert_eq!(stored["message"][1], rows[1]);
    assert_eq!(stored["message"][2]["data"], "appended");
}

#[test]
fn primitive_variables_and_noop_effects_match_on_store_and_overlay_sources() {
    let budget = budget();
    let records = snapshot(&json!([]), &json!({"$same":"same", "$remove":"old", "$integer":1, "$zero":0}));
    let code = r#"function onStart(id)
        assert(setChatVarChanged(id,'same','same')==nil)
        assert(setChatVarChanged(id,'integer',1)==nil and setChatVarChanged(id,'zero',-0.0)==nil)
        setChatVar(id,'same','same')
        assert(setChatVarChanged(id,'number',1.5)==true)
        assert(getChatVar(id,'number')==1.5)
        assert(setChatVarChanged(id,'number',1.5)==nil)
        setChatVar(id,'bool',false); assert(getChatVar(id,'bool')==false)
        setChatVar(id,'nil',nil); assert(getChatVar(id,'nil')==null)
        setChatVar(id,'remove'); assert(getChatVar(id,'remove')=='old')
        return true
    end"#;
    let request = trigger_request(code,"start",false,LuaDeadline::Listener,LuaView::default(),&budget);
    let HostReply::Lua(reply) = run_trigger(&mut host(), &records, request, &budget).unwrap() else { panic!("Lua reply") };
    assert!(matches!(reply.value, Value::Bool(true)));
    assert_eq!(reply.effects.len(),4);
    assert_eq!(variable(&reply.effects[0]).unwrap().0,"number");
    assert!(matches!(variable(&reply.effects[0]).unwrap().1,Value::Number(1.5)));
    assert!(matches!(variable(&reply.effects[1]).unwrap().1,Value::Bool(false)));
    assert!(matches!(variable(&reply.effects[2]).unwrap().1,Value::Null));
    assert!(matches!(variable(&reply.effects[3]).unwrap().1,Value::Undefined));

    let (_directory, store) = fixture(&json!([]), &json!({"$same":"same", "$remove":"old", "$integer":1, "$zero":0}));
    let pool=AccessPool::new(settings()).unwrap(); let access=scope(&store,&pool);
    let request=trigger_request(code,"start",false,LuaDeadline::Listener,LuaView::default(),&budget);
    let HostReply::Lua(reply)=answer(&mut host(), request, Context { owner:"char-b", triggers:&[],
        records:Records::Store { access:&access,store:&store }, cancellation:&Cancellation::default(), budget:&budget }).unwrap() else { panic!("Lua reply") };
    assert!(matches!(reply.value,Value::Bool(true))); assert_eq!(reply.effects.len(),4);
    commit(&access,&store);
    let stored=conversation(&store);
    assert_eq!(stored["scriptstate"]["$number"],1.5);
    assert_eq!(stored["scriptstate"]["$bool"],false);
    assert_eq!(stored["scriptstate"]["$nil"],Json::Null);
    assert!(stored["scriptstate"].get("$remove").is_none());
    assert_eq!(stored["scriptstate"]["$same"],"same");
}

#[test]
fn an_unrecordable_write_preserves_exactly_the_prepared_prefix() {
    let budget=Budget::new(risunest_ir::Limits { max_text_units:32,..ir_limits() },Default::default()).unwrap();
    let records=one_row();
    let code="function onStart(id) setChatVar(id,'before','kept'); setChatVar(id,'oversized',string.rep('x',33)); setChatVar(id,'after','lost') end";
    // Source text uses a separate input budget, as a real job's deserialized request does.
    let input_budget=super::lua_edit_tests::budget();
    let request=trigger_request(code,"start",false,LuaDeadline::Listener,LuaView::default(),&input_budget);
    let request=match request { HostRequest::Lua { mode,trigger:LuaTrigger::Effect {trigger,effect,..},payload,view } => {
        let call=LuaCall {code:Text::from_str(code,&input_budget).unwrap(),entry:Text::from_str("start",&input_budget).unwrap(),low_level:false,deadline:LuaDeadline::Listener};
        HostRequest::Lua {mode,trigger:LuaTrigger::Effect {trigger,effect,call},payload,view}
    },_=>unreachable!() };
    let failure=run_trigger(&mut host(),&records,request,&budget).unwrap_err();
    assert_eq!(failure.reason,"lua-host-limit");
    assert_eq!(failure.edits,[Edit::Variable {key:"before".into(),value:"kept".into()}]);
    assert_eq!(failure.saved.effects.len(),1);
    assert_eq!(variable(&failure.saved.effects[0]).unwrap().0,"before");
    assert_eq!(text_of(variable(&failure.saved.effects[0]).unwrap().1),Some("kept"));
}

#[test]
fn retained_edit_memory_is_bounded_across_repeated_small_writes() {
    use super::lua_edit::{Call, CallStatus};
    use super::lua_view::Overlay;
    const CAP:usize=64<<10;
    let budget=Budget::new(risunest_ir::Limits {max_owned_bytes:CAP,..ir_limits()},Default::default()).unwrap();
    let source:Rc<dyn Conversation>=Rc::new(Overlay::new(one_row(),&LuaView::default(),true,&budget).unwrap());
    let code="function onStart(id) for i=1,10000 do setChatVar(id,'k',tostring(i)..string.rep('v',64)) end end";
    let mut host=host();
    let outcome=host.call(Call {owner:"char-b",code,entry:"start",low_level:false,deadline:LuaDeadline::Listener,source:&source,
        cancellation:&Cancellation::default(),budget:&budget}).unwrap();
    assert_eq!(outcome.status,CallStatus::Declined("lua-host-limit".into()));
    assert!(!outcome.edits.is_empty() && outcome.edits.len()<10000);
    let retained_minimum=outcome.edits.len()*(std::mem::size_of::<Edit>()+std::mem::size_of::<Effect>()+65);
    assert!(retained_minimum<=CAP,"journal retains at least {retained_minimum} bytes beyond its budget");
    let observed=super::lua_edit_tests::budget();
    let acknowledged=acknowledged_variables(&outcome.saved,&observed);
    assert_eq!(acknowledged.as_array().unwrap().len(),outcome.edits.len());
    for (index,entry) in acknowledged.as_array().unwrap().iter().enumerate() {
        assert_eq!(entry,&json!(["k",["string",format!("{}{}",index+1,"v".repeat(64))]]));
    }
    let last=acknowledged.as_array().unwrap().last().unwrap()[1][1].as_str().unwrap();
    let effects=source.finish_variables(VariableFinish::Failure).unwrap();
    assert_eq!(effects.len(),1);
    let (key,value)=variable(&effects[0]).unwrap();
    assert_eq!((key,text_of(value)),("k",Some(last)));
    let applied=LuaView {effects,locals:vec![]};
    let owner:Rc<dyn Conversation>=Rc::new(Overlay::new(one_row(),&applied,false,&observed).unwrap());
    let read=host.call(Call {owner:"char-b",code:"function onStart(id)return getChatVar(id,'k')end",entry:"start",low_level:false,
        deadline:LuaDeadline::Listener,source:&owner,cancellation:&Cancellation::default(),budget:&observed}).unwrap();
    assert_eq!(read.status,CallStatus::Returned);
    assert_eq!(text_of(&read.value),Some(last));
    drop(read);drop(owner);drop(applied);
    let held_before_drop=budget.owned_bytes();
    drop(outcome);
    assert!(budget.owned_bytes()<held_before_drop,"completed journal retains its acknowledged writes");
    let next=host.call(Call {owner:"char-b",code:"function onStart(id) setChatVar(id,'healthy','yes');return true end",entry:"start",
        low_level:false,deadline:LuaDeadline::Listener,source:&source,cancellation:&Cancellation::default(),budget:&budget}).unwrap();
    assert_eq!(next.status,CallStatus::Returned);
    assert!(matches!(next.value,Value::Bool(true)));
    assert_eq!(acknowledged_variables(&next.saved,&observed),json!([["healthy",["string","yes"]]]));
    let effects=source.finish_variables(VariableFinish::Failure).unwrap();
    assert_eq!(effects.len(),1);
    assert_eq!(variable(&effects[0]).map(|(key,value)|(key,text_of(value))),Some(("healthy",Some("yes"))));
    drop(effects);drop(next);drop(source);
    assert_eq!(budget.owned_bytes(),Budget::context_bytes());
}

