#[test]
fn persona_matcher_objects_keep_catchable_errors_and_the_existing_named_envelope_refusal() {
    use risunest_cbs_experimental::cbs::processor::{Processor,Snapshot};
    use risunest_ir::rng::Tape;
    use super::lua_view::PersonaProcessor;
    for (value,refused) in [
        ("{a=1}",false),
        ("{__proto__=null}",false),
        ("{var=null,__proto__={var={}}}",false),
        ("{__proto__={var=null}}",false),
        ("{text='X',var={}}",true),
        ("{__proto__={text='P',var={}}}",true),
    ]{
        let budget=budget();
        let records=Arc::new(ConversationSnapshot {root:json!({"personaPrompt":"{{getvar::k}}"}),..ConversationSnapshot::default()});
        let processor:PersonaProcessor=Rc::new(RefCell::new(Box::new(Processor::new(Snapshot::default(),Tape::new(Vec::new())))));
        let code=format!("function onStart(id)setChatVar(id,'before','kept');setChatVar(id,'k',{value});local ok=pcall(getPersonaDescription,id);assert(not ok);setChatVar(id,'after','kept');return true end");
        let request=trigger_request(&code,"start",false,LuaDeadline::Listener,LuaView::default(),&budget);
        let reply=answer(&mut host(),request,Context {owner:"char-b",triggers:&[],records:Records::ProcessedSnapshot(&records,&processor),cancellation:&Cancellation::default(),budget:&budget});
        if refused{
            let failure=reply.unwrap_err();
            assert_eq!(failure.reason,"lua-host-error:getPersonaDescription","{value}");
            assert_eq!(failure.saved.effects.len(),2,"{value}");
        }else{
            let HostReply::Lua(reply)=reply.unwrap() else{panic!("Lua reply: {value}")};
            assert!(matches!(reply.value,Value::Bool(true)),"{value}");
            assert_eq!(reply.effects.len(),3,"{value}");
            assert_eq!(variable(&reply.effects[2]).unwrap().0,"after");
        }
    }
}

